class Resource extends Base {
 mount(){this.queue=new Map();this.saved=0;this.render(`<section class="scene panel"><header><span class="label">FEEDBACK THAT KNOWS WHEN TO LEAVE</span><h2>A little reassurance.</h2><p class="hint">Useful feedback, a way to undo, and room to keep working.</p></header><div class="document"><div class="page-mark">▤</div><div><strong>Working notes</strong><p data-count>No changes saved yet.</p></div><span class="tag">DRAFT</span></div><div class="actions"><button class="primary" data-save>Save a change ↗</button><button class="secondary" data-task>Finish a background task</button></div><ol aria-label="Notifications"></ol><p class="footnote">Notifications pause while hovered, focused, or the tab is hidden.</p><div class="sr-only" role="status" aria-live="polite"></div></section>`,`.scene{min-height:510px;padding:32px;background:var(--bg);position:relative}h2{font:400 clamp(29px,5vw,40px) Georgia;letter-spacing:-1px;margin:12px 0}.document{display:flex;align-items:center;gap:15px;border:1px solid var(--line);border-radius:12px;padding:22px;margin:28px 0 20px;background:var(--panel)}.page-mark{display:grid;place-items:center;width:42px;height:48px;border:1px solid #9cb29444;border-radius:7px;font-size:22px;color:var(--accent)}.document strong{font-size:13px;font-weight:500}.document p{font-size:11px;color:var(--muted);margin-top:7px}.tag{margin-left:auto;font-size:7px;letter-spacing:1px;padding:5px 7px;border:1px solid var(--line);border-radius:5px;color:var(--muted)}.actions{display:flex;flex-wrap:wrap;gap:9px}.actions button{font-size:11px}ol{list-style:none;margin:26px 0 0;padding:0;display:flex;flex-direction:column;gap:10px;min-height:104px}li{position:relative;display:flex;align-items:flex-start;gap:12px;padding:16px 15px 18px;border:1px solid #a6bb933e;background:var(--panel);border-radius:10px;overflow:hidden}.check{display:grid;place-items:center;width:22px;height:22px;border:1px solid #a6bb9344;border-radius:50%;font-size:11px;color:var(--accent);flex-shrink:0}.toast-copy{flex:1;min-width:0}.toast-copy strong{font-size:12px;font-weight:550}.toast-copy p{font-size:11px;color:var(--muted);margin-top:5px;line-height:1.6}.toast-controls{display:flex;align-items:center;gap:8px}.toast-controls button{border:0;background:none;font-size:11px;color:var(--accent);padding:4px}.toast-controls [data-dismiss]{color:var(--muted);font-size:18px}.life{position:absolute;bottom:0;left:0;right:0;height:2px;background:#a6bb9310}.life i{display:block;height:2px;background:var(--accent);transform-origin:left}.footnote{font-size:9px;color:var(--muted);line-height:1.8;margin-top:15px}@media(max-width:480px){.scene{padding:25px 19px}.document{padding:17px 14px;gap:11px}.tag{display:none}.actions{flex-direction:column}.actions button{text-align:left}li{padding:14px 11px 17px;gap:8px}.toast-controls{gap:3px}}`);this.listen(this.$('[data-save]'),'click',()=>{this.saved++;this.paintCount();this.notify({title:'Change saved.',message:'Your working notes have a new version.',action:{label:'Undo',run:()=>{this.saved=Math.max(0,this.saved-1);this.paintCount();}}});});this.listen(this.$('[data-task]'),'click',()=>this.notify({title:'Your export is ready.',message:'The example background task is complete.'}));this.listen(this.$('ol'),'click',e=>{const action=e.target.closest('[data-action]'),close=e.target.closest('[data-dismiss]');if(action){const item=this.queue.get(action.dataset.action);item?.action?.run?.();this.emit('toast-action',{id:item.id});this.dismiss(item.id);}if(close)this.dismiss(close.dataset.dismiss);});this.listen(this.$('ol'),'pointerover',e=>{const li=e.target.closest('li');if(li)this.pauseToast(li.dataset.id);});this.listen(this.$('ol'),'pointerout',e=>{const li=e.target.closest('li');if(li&&!li.contains(e.relatedTarget)&&!li.contains(this.shadowRoot.activeElement))this.resumeToast(li.dataset.id);});this.listen(this.$('ol'),'focusin',e=>{const li=e.target.closest('li');if(li)this.pauseToast(li.dataset.id);});this.listen(this.$('ol'),'focusout',e=>{const li=e.target.closest('li');if(li&&!li.contains(e.relatedTarget)&&!li.matches(':hover'))this.resumeToast(li.dataset.id);});this.listen(document,'visibilitychange',()=>{for(const id of this.queue.keys())document.hidden?this.pauseToast(id):this.resumeToast(id);});this.animate(()=>{for(const item of this.queue.values()){const remaining=item.started?item.remaining-(performance.now()-item.started):item.remaining;const bar=this.$(`[data-id="${item.id}"] .life i`);if(bar)bar.style.transform=`scaleX(${clamp(remaining/item.total)})`;}});}
 paintCount(){this.$('[data-count]').textContent=this.saved?`${this.saved} ${this.saved===1?'change':'changes'} saved in this example.`:'No changes saved yet.';}
 notify({title,message='',action}={}){if(!title)return null;while(this.queue.size>=4)this.dismiss(this.queue.keys().next().value);const id=uid(),total=this.number('duration',5000,2000,10000);const item={id,title,message,action,total,remaining:total,started:0};this.queue.set(id,item);const li=document.createElement('li');li.dataset.id=id;li.innerHTML=`<span class="check" aria-hidden="true">✓</span><div class="toast-copy"><strong>${escape(title)}</strong><p>${escape(message)}</p></div><div class="toast-controls">${action?`<button data-action="${id}">${escape(action.label||'Undo')}</button>`:''}<button data-dismiss="${id}" aria-label="Dismiss ${escape(title)}">×</button></div><span class="life"><i></i></span>`;this.$('ol').append(li);this.$('[role=status]').textContent=`${title} ${message}`;this.tween(li,[{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'none'}],{duration:280});if(!document.hidden)this.resumeToast(id);return id;}
 pauseToast(id){const item=this.queue.get(id);if(!item||!item.started)return;item.remaining=Math.max(0,item.remaining-(performance.now()-item.started));clearTimeout(item.timer);item.started=0;}
 resumeToast(id){const item=this.queue.get(id);if(!item||item.started||document.hidden)return;item.started=performance.now();item.timer=setTimeout(()=>this.dismiss(id),item.remaining);}
 dismiss(id){const item=this.queue.get(id);if(!item)return;clearTimeout(item.timer);this.$(`[data-id="${id}"]`)?.remove();this.queue.delete(id);this.emit('toast-dismiss',{id});}
 teardown(){for(const item of this.queue?.values()||[])clearTimeout(item.timer);}
}
